mapper.select:
select u.*, d.name as department_name from user u left join department d on u.department_id = d.id and d.is_deleted = 0 where u.is_deleted = 0
and u.username like concat('%', #{username}, '%')
and u.real_name like concat('%', #{realName}, '%')
and u.department_id = #{departmentId}
and u.status = #{status}
order by u.id desc
